/* Project documentation. Each chapter identifies the source and scope of its claims. */
window.LAB = (() => {
  const rtl = 'https://github.com/spenchh/FPGA-foc-motor-control';
  const team = 'https://github.com/pmadaan1/SURG-2026';
  const teamRev = 'fefb1009a902686bd72c1ca644aba9bcf5fb22dc';
  const source = name => SOURCE_DATA.files.find(f => f.name === `${name}.sv` && f.path.startsWith('rtl/design'))?.url || rtl;
  const href = (url, text) => `<a href="${url}" target="_blank" rel="noopener">${text}</a>`;
  const refs = (...items) => `<div class="sources">${items.map(([u,t]) => href(u,t)).join('')}</div>`;
  const eq = s => `<div class="equation">${s}</div>`;
  const table = (headers, rows) => `<div class="table-scroll"><table><thead><tr>${headers.map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(t=>`<td>${t}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  const note = s => `<div class="note">${s}</div>`;
  const model = (id, caption) => `<figure class="figure"><div data-model="${id}"></div><figcaption>${caption} · Explanatory model</figcaption></figure>`;
  const section = (id, title, body) => ({id,title,body});
  const modules = {
    adc_current_scaler_q15: {title:'ADC current scaler', role:'Converts three unsigned ADC codes into signed normalized current.', inputs:'adc_a/b/c, offset_a/b/c, scale_q, sample_valid', outputs:'ia_q, ib_q, ic_q, current_valid', latency:'3 register stages; output at E2 for acceptance at E0', equation:'delta = ADC − offset\ncurrent_q = sat((delta × scale_q) >>> 15)', why:'A bidirectional current sensor places zero current near an ADC offset. Subtracting that offset creates a signed measurement; calibration then maps it into the control system’s units.', detail:'The 12-bit ADC difference is held in 13 signed bits. A 13 × 24-bit multiplication uses a 37-bit product. Subtraction, multiplication, and shift/saturation are separated by registers. scale_s1 captures the gain with its sample.', boundaries:'The scale is a calibration coefficient, not an ampere rating. The test gain 32768 maps one ADC count to one output integer code. Real current calibration depends on sensor sensitivity and base current.'},
    sincos_lut_q15: {title:'Sine and cosine LUT', role:'Converts an unsigned electrical angle into two Q1.15 trigonometric values.', inputs:'angle_q, angle_valid', outputs:'sin_theta_q, cos_theta_q, sincos_valid', latency:'1 register stage; output at E0', equation:'quadrant = angle_q[15:14]\nindex = angle_q[13:8]\nsin/cos = mirrored quarter-wave values', why:'The transforms need sin θ and cos θ. A small lookup table and quadrant symmetry avoid iterative trigonometric arithmetic.', detail:'The 65-entry quarter-wave table includes 0 and 90 degrees. The cosine address mirrors the sine address around 64. Quadrant logic swaps signs and values, and one output register captures the result.', boundaries:'Only the top eight angle bits affect the result: 256 electrical positions, 1.40625 degrees per step. The lower eight bits are ignored. This implementation maps to logic rather than BRAM.'},
    clarke_park_transform: {title:'Clarke and Park transforms', role:'Expresses three phase currents as stationary αβ, then rotating dq components.', inputs:'ia_q, ib_q, ic_q, sin_theta_q, cos_theta_q, sample_valid', outputs:'i_alpha_q, i_beta_q, i_d_q, i_q_q, transform_valid', latency:'4 register stages; output at E3', equation:'α = ia\nβ = (ib − ic) / √3\nd = α cos θ + β sin θ\nq = β cos θ − α sin θ', why:'With the axes rotating alongside the rotor field, sinusoidal phase currents become nearly constant dq values that PI control can regulate.', detail:'The first stage captures ia, ib−ic, and the angle. The next multiplies by 18919, the Q1.15 approximation to 1/√3. Four Park products follow. The final stage adds full-width products before shifting and saturating. Diagnostic balance state follows the same stage enables.', boundaries:'α=ia is the balanced three-wire simplification. A general αβ0 transform would handle zero sequence explicitly. The exact nonzero-sum warning differs from the tolerance-based protection monitor.'},
    pi_controller_q15: {title:'PI current controller', role:'Regulates one measured current axis against its reference.', inputs:'reference_q, feedback_q, kp_q, ki_q, limits, enable, clear_integrator, sample_valid', outputs:'output_q, error_q, integrator_q, control_valid', latency:'4 register stages; output at E3', equation:'e = reference − feedback\nP = (Kp × e) >>> 15\nI_next = clamp(I + ((Ki × e) >>> 15))\nu = clamp(P + I_next)', why:'The proportional term reacts to the present error. The integral term removes persistent error. Two instances independently regulate d and q.', detail:'The signed error is 17 bits to preserve a full-range subtraction. Products are 33 bits. Limits move through the pipeline with the sample. The extra p_term_s3 and integrator_s3 registers split the integrator/clamp work from the final add/clamp path.', boundaries:'Integrator clamping bounds accumulation; it is not back-calculation anti-windup. Ki is a discrete per-update gain and must include the chosen sample interval. Gains must remain stable through the multiplication stage. Disable during in-flight transactions needs additional boundary tests.'},
    inverse_park_transform: {title:'Inverse Park transform', role:'Rotates dq voltage commands back into the stationary αβ frame.', inputs:'v_d_q, v_q_q, sin_theta_q, cos_theta_q, sample_valid', outputs:'v_alpha_q, v_beta_q, inverse_valid', latency:'2 register stages; output at E1', equation:'vα = vd cos θ − vq sin θ\nvβ = vd sin θ + vq cos θ', why:'The controller reasons in rotating coordinates, but the inverter must command stationary physical phases.', detail:'Four products are registered in the first stage. Each sum uses one extra bit, then shifts once and saturates in the output stage. Adding before truncation retains more fractional information.', boundaries:'The top currently supplies the latest held angle. Matching each angle to its original current transaction remains an integration task.'},
    alpha_beta_to_duty: {title:'Phase duty generation', role:'Reconstructs three phase voltage commands and maps them to timer counts.', inputs:'v_alpha_q, v_beta_q, period, sample_valid', outputs:'duty_a, duty_b, duty_c, duty_valid', latency:'3 register stages; output at E2', equation:'a = α\nb = −α/2 + √3 β/2\nc = −α/2 − √3 β/2\nduty = clip(period/2 + phase_q × period / 65536)', why:'The modulator turns a normalized voltage request into a comparator threshold for each phase of the PWM timer.', detail:'Stage one calculates the −1/2 and √3/2 products. Stage two forms a/b/c. Stage three multiplies by the timer period, adds the midpoint, and clips to 0…period. The period is registered alongside the data.', boundaries:'This is sine PWM style phase reconstruction, not space-vector PWM. The output mapping assumes normalized voltage commands; bus-voltage compensation is not implemented.'},
    pwm_3phase_center_aligned: {title:'Center-aligned PWM', role:'Generates high and low logic signals for each of three inverter legs.', inputs:'duty_a/b/c, period, nonoverlap_ticks, enable, pwm_inhibit', outputs:'pwm_hi/lo_a/b/c, cycle_strobe, pwm_peak_strobe, configuration_error', latency:'Counter runs continuously; settings activate at a cycle boundary', equation:'high = active && counter + gap &lt; duty\nlow = active && counter &gt; duty + gap\nfPWM = fclk / (2 × period)', why:'A triangular counter gives symmetric switching. Shadow/active registers apply all phase settings together. A non-overlap window prevents simultaneous high/low commands.', detail:'Inputs first enter shadow registers. At the counter’s valley, a complete shadow configuration becomes active. Invalid period, excessive gap, or duty greater than period raises configuration_error. Outputs are registered and inhibited when protection is active.', boundaries:'Three duty commands expand into six physical outputs. nonoverlap_ticks defines a comparator window; it must not be quoted as measured gate deadtime. Gate-driver delay and hardware deadtime still matter.'},
    phase_current_limit_monitor: {title:'Phase overcurrent monitor', role:'Checks each phase magnitude independently against a configured threshold.', inputs:'ia_q, ib_q, ic_q, current_limit_q, sample_valid', outputs:'phase_over_limit[2:0], current_out_of_range', latency:'Combinational; result registered by the FOC top', equation:'over_limit = valid && |phase current| &gt; |limit|', why:'Large currents can sum to zero, so the phase-balance check alone cannot detect overcurrent.', detail:'The block calculates signed magnitudes and compares A, B, and C independently. A reduction OR combines the three flags. The top-level register limits the combinational path into global disable logic.', boundaries:'abs(−32768) does not fit in signed 16 bits. This negative endpoint needs a wider magnitude or explicit special case before hardware use.'},
    phase_current_balance_monitor: {title:'Phase current balance', role:'Checks the consistency of three current measurements.', inputs:'ia_q, ib_q, ic_q, balance_limit_q, sample_valid', outputs:'balance_error_q, balance_abs_q, balance_out_of_range', latency:'Combinational; result registered by the FOC top', equation:'sum = ia + ib + ic\ntrip = valid && |sum| &gt; |balance_limit|', why:'A three-wire motor should have near-zero total phase current. A large residual can indicate calibration, wiring, or measurement errors.', detail:'Each 16-bit phase is sign-extended to 18 bits before addition. The absolute sum is compared with the absolute configured tolerance. limit_abs_q is an internal magnitude of balance_limit_q, not a second threshold.', boundaries:'The tolerance must reflect offset error, ADC sampling skew, noise, and sensor gain mismatch. It is not a motor-current rating.'},
    pcb_disable_control: {title:'Latched disable control', role:'Combines startup readiness, enable requests, and protection state.', inputs:'sensor_data_valid, enable_request, current/voltage faults, external_inhibit_request, clear_latch', outputs:'pwm_enable, disable_cmd, protection_latched, status_code', latency:'Present inhibits gate pwm_enable combinationally; fault history registers on clk', equation:'pwm_enable = !rst && request && !latched && !inhibit\nDISABLE = !pwm_enable  (active-high configuration)', why:'A transient fault must keep the drive off until it is acknowledged and the underlying condition has cleared.', detail:'Priority is startup, current, voltage, then external inhibit. Current, voltage, and external faults set protection_latched. A clear command is accepted only with no current inhibit. Startup intentionally inhibits without retaining a fault.', boundaries:'In the standalone block, losing sensor readiness clears fault history. The integrated sensor_ready signal remains set until reset. A stale-sample watchdog and explicit restart policy are still needed.'},
    hall_decoder: {title:'Hall sector decoder', role:'Captures three external Hall signals and checks sector transitions.', inputs:'hall_a, hall_b, hall_c, clk, rst', outputs:'sector, hall_valid, direction_forward, transition_strobe, illegal_state, counters', latency:'Two input synchronization registers plus a registered decode', equation:'001 → 0 → 101 → 1 → 100 → 2\n110 → 3 → 010 → 4 → 011 → 5', why:'External Hall transitions are asynchronous to the FPGA clock. Synchronization and legal-state checks provide a usable digital rotor-sector signal.', detail:'hall_sync_0 and hall_sync_1 form the synchronizer. Six patterns map to sectors; 000 and 111 are invalid. Adjacent sector transitions identify direction. Skipped or illegal transitions update error flags/counters.', boundaries:'The Hall block is tested separately and is not instantiated in the FOC top. A sector covers 60 electrical degrees; interpolation, phase order, and angle offset are needed for continuous-angle FOC.'},
    voltage_sense_monitor: {title:'Voltage range monitor', role:'Checks phase and bus voltage readings against configurable ranges.', inputs:'phase_v_q, bus_v_q, phase and bus min/max', outputs:'phase_v_out_of_range, bus_v_out_of_range, voltage_out_of_range', latency:'Combinational', equation:'out_of_range = value &lt; minimum || value &gt; maximum', why:'The drive must inhibit when sensed voltage leaves its operating range.', detail:'Two independent unsigned window comparisons feed an OR. These code values require an agreed voltage conversion; the `_q` suffix alone does not define the physical scale.', boundaries:'The FOC top takes voltage_out_of_range as an external flag. This module is not instantiated inside the current top.'},
    foc_current_loop_top: {title:'Integrated current loop', role:'Connects the scaler, transforms, controllers, modulator, PWM, and protection.', inputs:'three ADC samples, electrical angle, references, gains, limits, enable and inhibit requests', outputs:'currents, duty counts, complementary PWM, DISABLE, status', latency:'Multiple stages and registered handoffs; end-to-end latency is not a measured résumé metric', equation:'ADC → scale → Clarke/Park → d/q PI → inverse Park → duty → PWM', why:'Each block has a different latency. The integration layer coordinates valid events, persistent readiness, and shutdown.', detail:'sensor_ready, angle_ready, and duty_ready latch the first completed result. transform_sample_valid, inverse_sample_valid, and duty_sample_valid are registered handoffs. The current and balance protection results are also registered before global gating.', boundaries:'Latest-held angles and delayed valid-only handoffs are not a transaction-aligned stream for arbitrary changing inputs. The existing static-angle test passes; varying-angle and back-to-back alignment need dedicated tests.'}
  };
  const pages = [
    {id:'home',home:true,title:'FPGA Field-Oriented Control for Lightweight Motors',nav:'Research introduction',group:'The project',lede:'An undergraduate research project investigating FPGA computation for current control in lightweight three-phase motor drives.',sections:[
      section('research-question','The research question',`<p>Can an FPGA-based field-oriented controller provide a practical foundation for efficient, lower-cost motor drives in lightweight vehicles?</p><p>The research examined the control architecture behind that question: sensing phase current, performing fixed-point control math, and generating deterministic inverter commands. Applications such as solar vehicles and UAVs motivated the focus on controller cost, size, and energy use.</p>`),
      section('approach','From control equations to FPGA logic',`<ol class="research-steps"><li><span>01</span><div><h3>Model the current loop</h3><p>Express three-phase current in rotating coordinates, regulate d/q current, and define fixed-point scaling.</p><a href="#/foc">FOC and the math →</a></div></li><li><span>02</span><div><h3>Build the hardware datapath</h3><p>Pipeline the transforms, PI regulators, modulation, and protection in SystemVerilog, with supervisory tasks assigned to the Zynq processor.</p><a href="#/architecture">Architecture and code →</a></div></li><li><span>03</span><div><h3>Evaluate the implementation</h3><p>Check arithmetic and fault behavior in simulation, then synthesize, place, route, and examine timing on an FPGA target.</p><a href="#/implementation">Implementation results →</a></div></li></ol>`),
      section('findings','Results of the RTL investigation',`<div class="metric-strip"><div class="metric"><b>100 MHz</b><span>Routed implementation wrapper</span></div><div class="metric"><b>+0.557 ns</b><span>Worst setup slack</span></div><div class="metric"><b>13 / 13</b><span>Directed RTL tests passing</span></div></div><p>The implemented current loop combines fixed-point transforms, two PI regulators, phase-duty generation, and protection. Pipelining the PI and protection paths changed post-route setup slack from −0.335 ns to +0.557 ns under the same 10 ns clock constraint.</p><p>These results establish the simulated behavior and implementation timing of the FPGA datapath. Comparative controller efficiency, system cost, and physical motor performance remain questions for hardware evaluation.</p>${refs(['assets/evidence/after-timing.rpt','Timing evidence'],['assets/evidence/regression.txt','Verification evidence'])}`),
      section('work','The research and the implementation',`<p>Spencer Kogoma developed the FPGA control path as part of Northwestern’s Summer Undergraduate Research Grant project in June–August 2026. The team’s work also included inverter-board design and MATLAB/Simulink motor models.</p><div class="research-end"><a href="#/overview">Continue to the project overview <span aria-hidden="true">→</span></a><a href="${team}" target="_blank" rel="noopener">Team models and hardware ↗</a></div>`)
    ]},
    {id:'overview',title:'FPGA motor control',nav:'Project overview',group:'The project',lede:'A fixed-point field-oriented current controller for a three-phase motor, implemented in SystemVerilog for a Zynq-7000 FPGA.',sections:[
      section('system','What the controller does',`<p>The controller measures motor phase currents, compares them with requested torque-producing and flux-producing current, and calculates new inverter switching commands. Field-oriented control (FOC) makes that comparison in coordinates that rotate with the motor’s magnetic field.</p>${model('system','Current feedback closes the path from the inverter back to the controller.')}`),
      section('result','Implemented and verified',`<div class="metric-strip"><div class="metric"><b>100 MHz</b><span>Post-route wrapper timing</span></div><div class="metric"><b>+0.557 ns</b><span>Worst setup slack</span></div><div class="metric"><b>13 / 13</b><span>Directed RTL tests passing</span></div></div><p>The RTL includes current scaling, Clarke/Park transforms, two PI regulators, inverse Park, duty conversion, complementary PWM, and protection. Vivado/xsim exercised the integrated current loop. Adding pipeline registers to PI control and protection paths resolved the original timing violation.</p><p>The routed result targets <code>xc7z010clg400-1</code> in a reduced-I/O implementation wrapper. The team’s later integration files target Cora Z7. Physical motor operation has not been demonstrated by the evidence published here.</p>${refs(['assets/evidence/after-timing.rpt','Routed timing'],['assets/evidence/regression.txt','Current regression'],[source('foc_current_loop_top'),'Current-loop RTL'])}`),
      section('scope','Research scope',`<p><a href="#/start">Start from zero</a> for the beginner path, or <a href="#/reproduce">recreate the simulations</a> before reading the detailed implementation.</p><p>SURG research explored an FPGA control path for lightweight motor applications. Spencer’s work focused on the fixed-point datapath, verification, timing closure, and protection interface. The team also developed inverter-board designs and MATLAB/Simulink models.</p><div class="path"><a href="#/motor"><small>01 · Physical system</small>Motor, inverter, sensing →</a><a href="#/transforms"><small>02 · Control math</small>From phase currents to dq →</a><a href="#/implementation"><small>03 · Implementation</small>From RTL to routed timing →</a></div>`)
    ]},
    {id:'motor',title:'Motor, inverter, and sensing',nav:'Motor & hardware',group:'The project',lede:'Three windings create the rotating field. An inverter sets their voltage; current and position feedback tell the controller how the motor responds.',sections:[
      section('parts','The physical loop',`<p>The stator carries phase A, B, and C windings, spaced 120 electrical degrees apart. The permanent-magnet rotor follows the rotating field. Three inverter legs connect the windings to a DC bus through high-side and low-side switches.</p>${model('motor','Winding axes and the electrical rotor angle. Pole-pair count is adjustable and illustrative.')}${eq('electrical angle = pole pairs × mechanical angle + alignment offset')}<p>Electrical angle tracks the magnetic field. A motor with several pole pairs completes several electrical cycles per mechanical revolution.</p>`),
      section('parameters','Parameters in the team model',`<p>The enabled BLDC block in <code>BLDC_qsparam_working.slx</code> contains the following parameters. These are archived simulation inputs. The Drive proposal names the Mitsuba M2096 as motivation, and later component notes name a QS260 candidate. Neither source establishes which physical motor was driven by this RTL or makes these model values measured specifications.</p>${table(['Model field','Stored value','Meaning'],[['p','16','Pole pairs'],['Rs','0.014 Ω','Stator resistance'],['Ld / Lq','150 µH / 150 µH','d/q inductance'],['Lambda','0.05 Wb','Permanent-magnet flux linkage'],['J','0.15 kg·m²','Rotor/load inertia'],['Sample time','10 µs','Discrete model step']])}<p>A commented-out motor block uses four pole pairs and different parameters. The separate reference RTL also sets four pole pairs while a nearby comment says seven. Those values cannot be treated as one consistent physical motor specification.</p>${refs([`${team}/blob/${teamRev}/BLDC_qsparam_working.slx`,'Team motor model'],[`${team}/blob/${teamRev}/src/fpga_top.v`,'Reference RTL settings'])}`),
      section('feedback','Feedback at the RTL boundary',`${table(['Signal','Physical meaning','Current implementation'],[['Phase current','Torque-related winding current','Three unsigned 12-bit sample inputs'],['Electrical angle','Rotor magnetic orientation','External 16-bit angle input'],['Hall A/B/C','Coarse rotor sector','Separate synchronized decoder'],['Voltage status','Bus/phase range check','External inhibit flag']])}<p>The current loop accepts digitized samples. ADC acquisition, scaling calibration, Hall interpolation, and the final board wiring remain integration work. A 40 A nominal current mentioned during planning does not define the allowable peak current or a calibrated protection threshold.</p>`)
    ]},
    {id:'foc',title:'Why field-oriented control?',nav:'FOC fundamentals',group:'The control math',lede:'FOC controls a rotating current vector by expressing it in a coordinate system that rotates with the rotor.',sections:[
      section('phase','Three currents, one vector',`<p>Balanced phase currents are sinusoids separated by 120 degrees. At any instant their sum is approximately zero. Their combined magnetic effect can therefore be described by two independent components instead of three.</p>${model('phases','Balanced phase currents through one electrical revolution.')}${eq('ia + ib + ic ≈ 0')}`),
      section('frames','Stationary and rotating frames',`<p>Clarke projects the phase currents onto stationary perpendicular α and β axes. Park rotates those axes through the electrical angle to obtain d and q. When the frame follows the rotor correctly, a steady torque command appears as nearly constant dq current.</p>${model('transform','The same current vector expressed in stationary αβ and rotating dq coordinates.')}<p>The d-axis aligns with the rotor’s magnet flux. The q-axis is perpendicular to it and produces torque. Setting <code>id_ref = 0</code> is a common starting point for a surface-PM motor below base speed; field weakening and saliency change that choice.</p>`),
      section('loop','The closed current loop',`<ol><li>Measure the phase currents and obtain electrical angle.</li><li>Transform the current into dq coordinates.</li><li>Compare d and q measurements with their references.</li><li>Calculate voltage commands with two PI controllers.</li><li>Transform the voltages back and update phase duty counts.</li></ol><p>A speed loop would generate the torque/current request above this inner loop. The implemented RTL is the inner current loop. It has no sensorless observer.</p>${refs(['https://www.mathworks.com/help/mcb/gs/field-oriented-control-foc.html','MathWorks: FOC'],[source('foc_current_loop_top'),'Implemented loop'])}`)
    ]},
    {id:'transforms',title:'Clarke, Park, and the return path',nav:'Coordinate transforms',group:'The control math',lede:'The transformations change the description of the current vector. They do not change the current flowing in the windings.',sections:[
      section('clarke','1. Phase currents to αβ',`${eq('iα = ia\niβ = (ib − ic) / √3')}<p>This RTL uses the balanced three-wire convention with phase A aligned to α. The β component is the difference between B and C scaled by <code>1/√3</code>. In Q1.15 that coefficient is <code>18919</code>.</p><p>For <code>ia=0.25, ib=−0.125, ic=−0.125</code>, α is 0.25 and β is zero. For an unbalanced system, a general αβ0 transform would also describe the zero-sequence component; the present α=ia simplification does not do that.</p>${refs(['https://www.mathworks.com/help/mcb/ref/clarketransform.html','Clarke convention'],[source('clarke_park_transform'),'RTL implementation'])}`),
      section('park','2. αβ to rotating dq',`${eq('id = iα cos θ + iβ sin θ\niq = iβ cos θ − iα sin θ')}${model('transform','The d-axis rotates with θ; the projection values change with the relative angle.')}<p>At θ=0, d=α and q=β. At θ=90°, d=β and q=−α. A wrong angle, swapped phase order, or sign convention changes these projections and can reverse or destabilize torque control.</p>${refs(['https://www.mathworks.com/help/mcb/ref/parktransform.html','Park convention'])}`),
      section('inverse','3. Voltage commands back to phases',`${eq('vα = vd cos θ − vq sin θ\nvβ = vd sin θ + vq cos θ\n\nva = vα\nvb = −vα/2 + √3 vβ/2\nvc = −vα/2 − √3 vβ/2')}<p>Inverse Park undoes the coordinate rotation. Phase reconstruction then creates three voltage requests. The duty generator uses coefficients <code>−16384</code> and <code>28378</code> for −0.5 and √3/2.</p><p>The RTL adds full-width Park products before the final rescaling shift. That retains fractional bits that would be lost by truncating each product first.</p>${refs([source('inverse_park_transform'),'Inverse Park'],[source('alpha_beta_to_duty'),'Phase reconstruction'])}`)
    ]},
    {id:'fixed',title:'From numbers to fixed-point hardware',nav:'Fixed point & scaling',group:'The control math',lede:'The datapath represents fractional values as signed integers. Widths, shifts, and saturation keep the arithmetic meaningful in hardware.',sections:[
      section('q15','Q1.15 in sixteen bits',`${eq('stored integer = round(real value × 32768)\nreal value = stored integer / 32768')}${table(['Value','Integer code','Meaning'],[['0.25','8192','One quarter of the chosen base'],['0.5','16384','One half'],['−0.5','−16384','Negative one half'],['Maximum','32767','0.999969…'],['Minimum','−32768','−1.0']])}${model('fixed','Q1.15 encoding and output saturation.')}<p><code>_q</code> names a fixed-point value. It does not declare units. Current requires a chosen ampere base; voltage needs a consistent normalization. The electrical angle uses an unsigned full-turn encoding, not signed Q1.15.</p>`),
      section('product','Multiplication and saturation',`${eq('16384 × 8192 = 134217728\n134217728 >>> 15 = 4096\n4096 / 32768 = 0.125')}<p>Two values with 15 fractional bits produce a product with 30 fractional bits. An arithmetic right shift removes 15 of them. Signed <code>&gt;&gt;&gt;</code> propagates the sign bit; a negative result rounds toward negative infinity when fractional bits are discarded.</p><p>Saturation clips values to −32768…32767 before narrowing. Without it, overflow can wrap a large positive command into a negative number. Sign extension copies the original sign bit into a wider operand before signed arithmetic or comparison.</p>`),
      section('adc','ADC counts to current',`${eq('delta = ADC code − zero-current offset\ncurrent_q = sat((delta × scale_q) >>> 15)')}<p>A 12-bit ADC reports 0…4095. If zero current corresponds to code 2048, code 2148 means +100 counts relative to zero and code 1948 means −100 counts. Counts become amperes only after calibration.</p>${eq('scale_q ≈ round((amps per ADC count / base current) × 2³⁰)')}<p>The extra factor of 2¹⁵ compensates for the scaler’s right shift. The testbench’s <code>scale_q=32768</code> makes the output integer equal the ADC delta. It verifies arithmetic, not real sensor calibration.</p>${refs([source('adc_current_scaler_q15'),'Current scaler'])}`)
    ]},
    {id:'pi',title:'Two PI current regulators',nav:'PI current control',group:'The control math',lede:'Each axis compares its measured current with a reference and calculates the voltage needed to reduce the error.',sections:[
      section('equations','Proportional response and integral memory',`${eq('e[k] = reference[k] − feedback[k]\nP[k] = Kp × e[k]\nI[k] = clamp(I[k−1] + Ki × e[k])\nu[k] = clamp(P[k] + I[k])')}<p>P responds to the present error. I accumulates error over accepted updates, allowing the controller to remove a persistent offset. The discrete Ki coefficient must account for the update interval. The FPGA clock alone does not establish the control-loop sample rate.</p>${model('pi','Illustrative PI state over accepted samples; this is not a motor-plant simulation.')}`),
      section('example','A testbench calculation',`${table(['Quantity','Integer code','Real value'],[['Reference','8192','0.25'],['Feedback','4096','0.125'],['Error','4096','0.125'],['Kp','16384','0.5'],['Ki','8192','0.25'],['First P','2048','0.0625'],['First I','1024','0.03125'],['First output','3072','0.09375']])}<p>Accepting the same error a second time makes I=2048 and output=4096. Clearing the integrator leaves the proportional response, output=2048. The directed test checks those exact codes.</p>`),
      section('hardware','Why the extra pipeline register matters',`<p>The original critical path combined integrator arithmetic, clamping, and downstream control logic. Registers <code>integrator_s3</code> and <code>p_term_s3</code> now separate the integrator update from the final output add/clamp. The corresponding valid pipeline gained one stage.</p><p>Integrator clamping bounds I at the configured limits. It is a simple anti-windup measure; it does not implement back-calculation from a saturated voltage-vector magnitude. Final gains and voltage normalization have not been tuned on a physical motor.</p>${refs([source('pi_controller_q15'),'PI source'],['assets/evidence/after-timing.rpt','Routed result'])}`)
    ]},
    {id:'architecture',title:'The PS/PL architecture',nav:'PS / PL architecture',group:'The implementation',lede:'Zynq combines an ARM processing system with programmable logic. The partition follows timing requirements and the kind of state each task owns.',sections:[
      section('partition','What belongs on each side',`${model('partition','Control data and configuration cross the proposed PS/PL boundary.')}${table(['Responsibility','Owner','Reason / status'],[['Current math and PWM','PL','Parallel arithmetic and repeatable clock timing; implemented RTL'],['Fault gating and latch','PL','Directly inhibits switching; implemented RTL'],['Hall synchronization','PL','Captures asynchronous sensor inputs; standalone module'],['Modes, references, gains','PS','Supervisory configuration; proposed integration'],['Calibration, CAN, logging','PS','Slower software tasks; proposed integration'],['AXI register interface','PS ↔ PL','Configuration/status bridge; not implemented']])}`),
      section('decision','How the partition follows the loop',`<p>The current loop repeats the same arithmetic for every sample and must update switching deterministically. Placing it in PL avoids dependence on software interrupt timing. Communication, parameter changes, calibration, and recovery are less frequent and easier to manage in ARM software.</p><p>The present top exposes parallel configuration ports. A real SoC integration would replace those external package pins with registers on an AXI interface and define how a complete parameter set is committed between samples. The repository does not yet contain that interface or the PS firmware.</p>`),
      section('boards','Board and implementation targets',`<p>The measured 100 MHz result targets <code>xc7z010clg400-1</code>, associated with the earlier Arty Z7-10 work. The team’s <code>foc.xdc</code> identifies a Cora Z7-07S Rev B constraint set and a 50 MHz <code>clk_50m</code> input.</p><p>Retargeting requires the actual part, clocking, reset, I/O banks, pin constraints, and another implementation run. The earlier 100 MHz result is preserved as a result for its specific wrapper and target.</p>${refs([`${team}/blob/${teamRev}/foc.xdc`,'Cora integration constraints'],['assets/evidence/after-timing.rpt','Measured XC7Z010 wrapper'])}`)
    ]},
    {id:'pipeline',title:'Following a sample through the pipeline',nav:'Pipeline & valid signals',group:'The implementation',lede:'Each register boundary divides arithmetic across clock cycles. A valid flag says when the associated result can be consumed.',sections:[
      section('registers','A clock edge captures old values',`<p>Inside <code>always_ff @(posedge clk)</code>, nonblocking assignments evaluate their right-hand sides using values from before the edge. All updated register values become visible together afterward. Thus <code>v2 &lt;= v1</code> delays validity instead of copying a newly assigned v1 in the same edge.</p>${model('pipeline','Register-stage illustration for an isolated transaction, with stable inputs and angle. E0 is the accepting edge.')}${table(['Block','Register stages','Local output edge'],[['ADC scaler','3','E2'],['Sine/cosine','1','E0'],['Clarke/Park','4','E3'],['PI controller','4','E3'],['Inverse Park','2','E1'],['Duty generator','3','E2']])}<p>These are source-derived block latencies. Registered handoffs between blocks add cycles. A simulation’s finish time is not a measurement of sample-to-duty latency.</p>`),
      section('readiness','Readiness persists; valid pulses do not',`<p><code>current_valid</code> marks a completed current sample. <code>sensor_ready</code> remembers that at least one current sample has arrived. Similarly, <code>duty_ready</code> persists after the first completed duty result. Using a one-cycle valid pulse as continuous permission to run would switch permission off between samples.</p>${eq('if (current_valid) sensor_ready <= 1\nif (duty_valid)    duty_ready <= 1')}<p>The readiness flags clear on reset. They do not detect stale measurements; that needs a watchdog or sample timeout.</p>`),
      section('alignment','Current integration boundary',`<p>The top holds the latest sine/cosine values. It also registers handoff valid pulses without capturing matching data at those handoffs. When samples change on adjacent clocks, a consumer can therefore observe data or angle from a different transaction.</p><p>The integrated directed test uses constant angle and largely steady currents, so it does not establish arbitrary streaming alignment. A complete streaming implementation needs transaction-matched data and angle delays, plus tests using distinct back-to-back samples and gaps.</p>${refs([source('foc_current_loop_top'),'Top-level handoffs'])}`)
    ]},
    {id:'rtl',title:'Inside the RTL',nav:'Annotated source',group:'The implementation',lede:'The source below is pinned to the current design revision. Each file is split into its interface, arithmetic, and register logic.',sections:[
      section('source','Module and testbench explorer','<div id="source-explorer"></div>'),
      section('conventions','Syntax and naming',`${table(['Syntax / suffix','Meaning'],[['logic signed [W−1:0]','A W-bit signed value; its driver determines whether it is registered'],['always_ff / &lt;=','Clocked state with nonblocking assignments'],['always_comb / =','Combinational logic with blocking assignments'],['assign / wire expression','Continuously evaluated combinational signal'],['_s1 / _s2 / _s3','Pipeline-stage registers'],['_q','Fixed-point coded value; units depend on calibration'],['_valid','The associated data is ready for acceptance'],['_ready','Persistent startup state in this top, not a ready/valid handshake'],['{N{bit}}','Replicates a bit, often for sign extension'],['function','Reusable combinational expression; no separate clock process']])}`)
    ]},
    {id:'pwm',title:'From duty counts to switching',nav:'PWM & non-overlap',group:'The implementation',lede:'A triangular timer compares each phase duty with its current count to produce symmetric high-side and low-side commands.',sections:[
      section('waveform','Center-aligned switching',`${model('pwm','Actual comparator equations, illustrated over two timer cycles.')}${eq('high = active && (counter + nonoverlap &lt; duty)\nlow  = active && (counter &gt; duty + nonoverlap)')}<p>Both outputs are low around the compare threshold. They are registered on the clock. The separation is a count-domain non-overlap window; actual gate deadtime also depends on the driver and power stage.</p>`),
      section('frequency','Clock, PWM, and control rates',`${eq('fPWM = fclk / (2 × period)')}${table(['FPGA clock','Period setting','PWM rate'],[['100 MHz','1000 (wrapper setting)','50 kHz'],['100 MHz','2500','20 kHz'],['50 MHz','1000','25 kHz']])}<p>The research notes used a 20 kHz target. The saved wrapper uses period=1000, corresponding to 50 kHz under its 100 MHz clock constraint. Neither value is a scope measurement. Current-loop updates have a separate sample_valid schedule.</p>`),
      section('updates','Atomic phase updates',`<p>The module captures new settings into shadow registers each cycle. At the timer valley it transfers the complete set to active registers. All three phase duties and the non-overlap setting therefore change together. A duty above period, zero period, or excessive non-overlap raises configuration_error and inhibits switching.</p><p>The RTL takes three duty values and emits six physical HI/LO signals. Any board using internally generated complementary outputs must have its interface reconciled with those six outputs.</p>${refs([source('pwm_3phase_center_aligned'),'PWM source'])}`)
    ]},
    {id:'protection',title:'Protection and shutdown',nav:'Fault protection',group:'The implementation',lede:'Current magnitude and current consistency are separate checks. Both can inhibit switching and retain a fault until cleared.',sections:[
      section('checks','Two current checks',`${eq('overcurrent:   any |phase current| &gt; current limit\nimbalance:     |ia + ib + ic| &gt; balance tolerance')}<p>Currents of +0.8, −0.4, −0.4 sum to zero but may exceed a phase limit. Currents of +0.1, +0.1, +0.1 can be individually small but inconsistent. The two monitors catch different conditions.</p>${model('fault','Startup, run, fault, and clear behavior for the integrated readiness/latch path.')}`),
      section('disable','Active-high DISABLE',`<p><code>disable_cmd=1</code> inhibits the gate drivers; zero allows operation when all conditions are satisfied. PWM enable requires an enable request, sensor readiness, no present inhibit, no reset, and no latched fault.</p><p>The priority order is startup, current, voltage, external inhibit. A clear request is accepted only after the fault sources have cleared. The top-level current and balance checks both feed the current-fault status code.</p>`),
      section('limits','Remaining boundary cases',`<p>The magnitude monitor must handle the most-negative signed value explicitly. Readiness needs a stale-sample timeout. A fault during a PI transaction needs a test for outstanding pipeline data and restart behavior. ADC-based FPGA protection also cannot replace a hardware shutdown path during configuration or power-stage faults.</p>${refs([source('phase_current_limit_monitor'),'Magnitude check'],[source('phase_current_balance_monitor'),'Balance check'],[source('pcb_disable_control'),'Disable control'])}`)
    ]},
    {id:'verification',title:'Verification results',nav:'Tests & evidence',group:'The results',lede:'Directed testbenches exercise arithmetic, startup, modulation, and protection. The published evidence records which tools ran and what was checked.',sections:[
      section('regression','Current directed regression',`<p>The SystemVerilog regression at design commit <code>${SOURCE_DATA.commit.slice(0,7)}</code> passed all 13 testbenches with Icarus on 26 October 2026. Each test requires its PASS marker and has a timeout; mismatches terminate the simulation.</p><div id="test-table"></div><pre><code>python rtl/sim/run_tests.py\n13/13 testbenches passed</code></pre>${refs(['assets/evidence/regression.txt','Preserved rerun summary'],[`${rtl}/blob/${SOURCE_DATA.commit}/rtl/sim/run_tests.py`,'Regression runner'])}`),
      section('toptest','Integrated current-loop test',`<p>The test begins with zero-current ADC offsets, θ=0, Id reference=0, Iq reference=4096, Kp=16384, and Ki=0. It checks nominal enable, no current fault, a valid PWM configuration, and duty B greater than duty C. Injecting a phase-A ADC code of 3200 then checks current trip, latched protection, and DISABLE.</p><p>The preserved xsim run finished at 516 ns. The PI xsim test finished at 216 ns. Those are test durations, including reset and checks. The current separate Hall regression finishes at 136 ns; the older xsim Hall test finished at 180 ns.</p>${note('The integrated test completes before a full 20 µs PWM period at period=1000. Complete switching-cycle checks are performed in the standalone PWM test, which runs for 7115 ns using a smaller period.')}`),
      section('coverage','Coverage boundaries',`<p>The suite uses directed expected-value checks. It does not contain a MATLAB-versus-RTL vector regression, numerical error statistics, formal proofs, or a motor-plant co-simulation. Arbitrary streaming angle alignment, full parameter sweeps, and physical motor operation remain unverified.</p><p>Team Simulink model files and waveform screenshots are available separately. Their presence does not establish equivalence with this fixed-point current-loop implementation.</p>${refs([`${team}/tree/${teamRev}/report`,'Team simulation and report artifacts'])}`)
    ]},
    {id:'implementation',title:'Closing timing at 100 MHz',nav:'Synthesis & timing',group:'The results',lede:'The first implementation routed but missed the clock requirement. Splitting the PI and protection paths created enough margin to meet the same constraint.',sections:[
      section('flow','The implementation flow',`${model('timing','Recorded setup slack before and after the pipeline changes.')}${table(['Stage','What Vivado does'],[['Synthesis','Maps RTL into LUTs, registers, and DSP arithmetic'],['Optimization','Simplifies the mapped logic'],['Placement','Chooses physical FPGA sites'],['Physical optimization','Improves the placed design'],['Routing','Connects sites through FPGA interconnect'],['Timing analysis','Checks actual placed-and-routed delays against constraints']])}`),
      section('wrapper','Why an implementation wrapper',`<p>The raw current-loop top exposes 449 bits of I/O while the target package has 230 available user I/Os. Synthesis succeeded but placement could not assign that many pins. <code>foc_synth_wrapper</code> generates changing internal inputs, supplies representative configuration constants, and reduces outputs into a 16-bit debug sink.</p><p>The wrapper permits implementation of the datapath without mapping every configuration bus to a package pin. It is not a board-ready integration. Configuration constants, preservation attributes, and the wrapper’s register logic affect the result.</p>${refs([`${rtl}/blob/${SOURCE_DATA.commit}/synth/foc_synth_wrapper.sv`,'Wrapper source'])}`),
      section('fix','What changed',`${table(['Metric','Original route','Pipelined route'],[['Target clock','10.000 ns','10.000 ns'],['WNS','−0.335 ns','+0.557 ns'],['TNS','−9.057 ns','0.000 ns'],['Failing setup endpoints','80','0'],['Worst hold slack','+0.140 ns','+0.034 ns']])}<p>The original worst path crossed PI/integrator-related generated logic with 18 logic levels and 10.216 ns data-path delay. The PI gained a register boundary before its final output add/clamp. Current-limit and balance results were registered before disable/PWM gating. The PI valid chain and testbench wait were updated for the new latency.</p><p>Both changes preceded the successful route, so the result does not isolate the contribution of either change. The final worst setup path is in duty generation, with 9.283 ns data-path delay and +0.557 ns slack.</p>${refs(['assets/evidence/before-timing.rpt','Before timing report'],['assets/evidence/after-timing.rpt','After timing report'])}`),
      section('resources','Where the arithmetic mapped',`${table(['Instance','DSP48E1 slices'],[['Current scaler','3'],['Clarke/Park','5'],['d-axis PI','2'],['q-axis PI','2'],['Inverse Park','4'],['Duty generator','4'],['Total','20']])}<p>The complete wrapper uses 1,292 LUTs, 668 registers, 20 DSP48E1 slices, and no BRAM. The wrapper itself accounts for 39 LUTs and 40 registers; all DSPs are in the current-loop instance. Those are counts for this configuration, not an optimization ratio or a guarantee for other targets.</p><p>Positive setup and hold slack establish timing for the specified constrained paths. The saved constraint creates a clock; it does not establish final external I/O timing or measured hardware frequency.</p>${refs(['assets/evidence/utilization.rpt','Hierarchical utilization'],['assets/evidence/implementation.tcl','Non-project flow'],['assets/evidence/clock.xdc','10 ns clock constraint'])}`)
    ]},
    {id:'pcb',title:'Board interface and team models',nav:'PCB & team artifacts',group:'The reference',lede:'The board work connects sensing, isolation, gate drive, and power switching. Its artifacts describe the team’s hardware path alongside the RTL.',sections:[
      section('driver','Driver-board schematic',`<p>The August schematic includes isolated UCC21222 gate-driver channels, current-sense amplifier paths, voltage-sense paths, Hall connections, and controller headers. The source image below preserves that design revision. The later component sheet lists UCC21222 drivers and shunt/AMC1300/OPA4388 current sensing; it supersedes earlier TMCS sensor exploration. This identifies the design direction, not an assembled-board validation.</p><figure class="figure"><a href="assets/images/driver-board.png" target="_blank" rel="noopener"><img class="schematic" src="assets/images/driver-board.png" alt="Team driver-board schematic showing isolated gate drivers, three current-sense paths, Hall inputs, and voltage sensing" loading="lazy"></a><figcaption>Team driver-board schematic · August 2026 design artifact · Open image for full resolution.</figcaption></figure>${refs([`${team}/blob/${teamRev}/report/driver_board_schematic.png`,'Original schematic image'])}`),
      section('power','Power-board schematic',`<p>The power stage contains three half bridges, phase outputs, current measurement points, and the DC link. Gate-drive signals command the MOSFETs; they do not carry the motor’s phase current.</p><figure class="figure"><a href="assets/images/power-board.png" target="_blank" rel="noopener"><img class="schematic" src="assets/images/power-board.png" alt="Team three-phase power-stage schematic" loading="lazy"></a><figcaption>Team power-board schematic · August 2026 design artifact.</figcaption></figure>${refs([`${team}/blob/${teamRev}/report/power_board_schematic.png`,'Original power-board schematic'])}`),
      section('interface','Interface contract',`${table(['Path','Information','Status'],[['Current input','Three digitized phase samples and zero offsets','RTL ports exist; physical acquisition/calibration pending'],['Angle input','Continuous electrical angle','RTL port exists; Hall-to-angle integration pending'],['Drive output','Three HI/LO pairs and active-high DISABLE','RTL implemented; final board mapping pending'],['Voltage input','Out-of-range flag','External integration required'],['PS interface','Gains, references, limits, enable, status','AXI register interface proposed']])}<p>The team repository also includes a second FOC/reference RTL path under <code>src/</code> and translated third-party material. Its synthesis report and simulation plots belong to that path, not automatically to Spencer’s Q1.15 loop. The code explorer identifies the exact revision documented here.</p>${refs([team,'Team repository'],[rtl,'Current datapath repository'])}`)
    ]},
    {id:'resources',title:'Sources and terminology',nav:'Resources & glossary',group:'The reference',lede:'Project evidence, source code, and primary references for the control math and FPGA tools.',sections:[
      section('project','Project sources',`<ul class="list-clean"><li>${href(rtl,'SystemVerilog design, tests, and simulation runner')}<br><small>Source revision ${SOURCE_DATA.commit.slice(0,7)} is embedded in the code explorer.</small></li><li>${href(team,'Team SURG repository')}<br><small>Motor models, Cora constraints, schematics, and separate reference RTL.</small></li><li>${href('assets/evidence/after-timing.rpt','100 MHz routed timing report')} · ${href('assets/evidence/before-timing.rpt','Original timing miss')}</li><li>${href('assets/evidence/utilization.rpt','Hierarchical utilization')} · ${href('assets/evidence/regression.txt','13-test regression summary')}</li></ul>`),
      section('primary','Primary technical references',`${table(['Topic','Reference','Used for'],[['FOC',href('https://www.mathworks.com/help/mcb/gs/field-oriented-control-foc.html','MathWorks FOC'),'Current-loop concepts'],['Clarke',href('https://www.mathworks.com/help/mcb/ref/clarketransform.html','Clarke transform'),'Coordinate conventions'],['Park',href('https://www.mathworks.com/help/mcb/ref/parktransform.html','Park transform'),'dq rotation equations'],['FPGA FOC',href('https://www.mathworks.com/help/hdlcoder/ug/field-oriented-control-of-a-PMSM.html','HDL Coder PMSM example'),'Software/hardware partitioning background'],['Cora Z7',href('https://digilent.com/reference/programmable-logic/cora-z7/reference-manual','Digilent reference manual'),'Board integration'],['Arty Z7',href('https://digilent.com/reference/programmable-logic/arty-z7/reference-manual','Digilent reference manual'),'Earlier target context'],['Timing',href('https://docs.amd.com/r/en-US/ug906-vivado-design-analysis','AMD UG906'),'Timing analysis'],['Implementation',href('https://docs.amd.com/r/en-US/ug904-vivado-implementation','AMD UG904'),'Place and route'],['Zynq',href('https://docs.amd.com/r/en-US/ug585-Zynq-7000-TRM','AMD UG585'),'PS, PL, and interconnect'],['Gate driver',href('https://www.ti.com/lit/ds/symlink/ucc21222.pdf','TI UCC21222'),'Gate-drive and DISABLE behavior'],['SimpleFOC',href('https://docs.simplefoc.com/','SimpleFOC documentation'),'Separate MCU motor-control reference']])}`),
      section('glossary','Terminology',`${table(['Term','Meaning'],[['FOC','Field-oriented control: regulation in a rotating reference frame'],['RTL','Register-transfer level: logic and state described in an HDL'],['PS / PL','Processing system / programmable logic on a Zynq SoC'],['ADC','Converts a sensed analog voltage into a digital code'],['Electrical angle','Rotor magnetic orientation, including pole-pair scaling'],['Per unit','A value normalized to a defined base quantity'],['PI','Proportional plus integral feedback controller'],['PWM','Switching waveform whose duty controls average phase voltage'],['DSP48E1','Dedicated multiplier/accumulator resource in the target FPGA'],['WNS / TNS','Worst setup slack / sum of negative setup slack'],['WHS / THS','Worst hold slack / sum of negative hold slack'],['Synthesis','Mapping RTL into a technology-specific logic network'],['Place and route','Physical location and interconnection of that network'],['Testbench','Stimulus and automatic checks around a design under test']])}`)
    ]}
  ];
  return {pages,modules,source,refs,table,rtl,team};
})();
